import org.elasticsearch.common.xcontent.XContentBuilder;
import org.elasticsearch.common.xcontent.XContentFactory;
import org.elasticsearch.index.mapper.RootObjectMapper;
import java.util.*;

public class RootObjectMapperExample {

    public static void main(String[] args) throws Exception {

        /* -------------------------------------------------------------
         * 1. Build the RootObjectMapper with the requested defaults
         * ------------------------------------------------------------- */
        RootObjectMapper rootMapper = new RootObjectMapper.Builder("my_index")
                // Dynamic date formats – the default value used by ES
                .dynamicDateFormats(
                        Collections.singletonList("strict_date_optional_time||epoch_millis"))
                // Dynamic templates – keep the default (empty) list
                .dynamicTemplates(Collections.emptyList())
                // Enable date detection
                .dateDetection(true)
                // Enable numeric detection
                .numericDetection(true)
                .build();

        /* -------------------------------------------------------------
         * 2. Create an XContentBuilder (JSON writer)
         * ------------------------------------------------------------- */
        XContentBuilder builder = XContentFactory.jsonBuilder();

        /* -------------------------------------------------------------
         * 3. Prepare the parameters map for the doXContent call
         * ------------------------------------------------------------- */
        Map<String, Object> params = new HashMap<>();
        params.put("includeDefaults", true);      // include default values
        params.put("skipRuntimeFields", true);    // skip runtime fields

        /* -------------------------------------------------------------
         * 4. Call the helper function (your provided Java 8 SDK wrapper)
         * ------------------------------------------------------------- */
        // Convert the builder and params to their string representations
        // (the wrapper expects strings, not actual objects)
        String builderString = builder.toString();          // e.g. "{}" after writing
        String paramsString = params.toString();            // e.g. "{includeDefaults=true, skipRuntimeFields=true}"

        // Invoke the function
        Object result = functions.RootObjectMapper_doXContent(new HashMap<String, Object>() {{
            put("builder", builderString);
            put("params", paramsString);
        }});

        /* -------------------------------------------------------------
         * 5. Inspect the output (the builder now contains the serialized mapper)
         * ------------------------------------------------------------- */
        System.out.println("Serialized XContent:");
        System.out.println(builderString);   // or builder.toString() after the call
    }
}
```

